code.java:
public int maxProfit(int[] prices) {
    int cash = 0;
    int hold = Integer.MIN_VALUE;
    for (int p : prices) {
        int prevCash = cash;
        cash = Math.max(cash, hold + p);
        hold = Math.max(hold, prevCash - p);
    }
    return cash;
}

